import { InitMessage, SyncMessage, CutMessage, CutProgressMessage, SetGravityMessage } from '../types';
import { LogModel } from './LogModel';
import { Solver, setGravity } from './Solver';

let logModel: LogModel;
let solver: Solver;
let positionsBuffer: Float32Array;
let strainsBuffer: Float32Array;

// Telemetry state
let showPerfWarnings = false;

// Tension Visualization State
let showTension = false;

// Hand Force State
// Hand Force State
let handForceActive = false;
let handForcePoint: [number, number, number] = [0, 0, 0];
let handForceDir: [number, number, number] = [0, 0, 0];
let handForceMag: number = 0;

let physicsInterval: ReturnType<typeof setInterval>;

self.onmessage = (e: MessageEvent) => {
  const data = e.data;

  if (data.type === 'INIT') {
    const initData = data as InitMessage;
    handForceActive = false;

    // Map ScenarioLogDef to LogDefinition
    const logDefs = initData.logs.map(log => ({
      radius: log.diameter / 2,
      length: log.length,
      radialSegments: log.radialSegments || 16,
      lengthSegments: log.lengthSegments || 16,
      position: log.position,
      rotation: [
        log.rotation[0] * Math.PI / 180,
        log.rotation[1] * Math.PI / 180,
        log.rotation[2] * Math.PI / 180
      ] as [number, number, number]
    }));

    logModel = new LogModel(logDefs);
    solver = new Solver(logModel);
    if (initData.terrain) {
      solver.setTerrain(initData.terrain);
    }

    // Allocate buffer
    positionsBuffer = new Float32Array(logModel.nodes.length * 3);
    strainsBuffer = new Float32Array(logModel.nodes.length);

    const springsArray = new Int32Array(logModel.springs.length * 2);
    for (let i = 0; i < logModel.springs.length; i++) {
      springsArray[i * 2] = logModel.springs[i].idxA;
      springsArray[i * 2 + 1] = logModel.springs[i].idxB;
    }

    self.postMessage({
      type: 'TOPOLOGY',
      segments: logModel.segments,
      kerfs: logModel.activeKerfs,
      springs: springsArray
    });

    self.postMessage({
      type: 'RESIZE_BUFFERS',
      nodeCount: logModel.nodes.length
    });

    // Start Loop
    if (physicsInterval) clearInterval(physicsInterval);
    physicsInterval = setInterval(tick, 1000 / 60);
  } else if (data.type === 'CUT_PROGRESS') {
    const progressData = data as CutProgressMessage;
    if (logModel) {
      const pX = progressData.boxPosition[0];
      const pY = progressData.boxPosition[1];
      const pZ = progressData.boxPosition[2];

      const qX = progressData.boxQuaternion[0];
      const qY = progressData.boxQuaternion[1];
      const qZ = progressData.boxQuaternion[2];
      const qW = progressData.boxQuaternion[3];

      // Inverse quaternion vector part
      const ux = -qX;
      const uy = -qY;
      const uz = -qZ;
      const w = qW;

      const sX = progressData.boxScale[0] / 2;
      const sY = progressData.boxScale[1] / 2;
      const sZ = progressData.boxScale[2] / 2;

      console.log(`[Physics Worker] CUT_PROGRESS received:
        boxPosition: [${pX.toFixed(3)}, ${pY.toFixed(3)}, ${pZ.toFixed(3)}]
        boxScale: [${progressData.boxScale.map(n => n.toFixed(3)).join(', ')}]
        halfScale: [${sX.toFixed(3)}, ${sY.toFixed(3)}, ${sZ.toFixed(3)}]
      `);

      let springsBroken = 0;

      for (const spring of logModel.springs) {
        if (spring.isKerf && !spring.broken) {
          const nA = logModel.nodes[spring.idxA];
          const nB = logModel.nodes[spring.idxB];

          // Transform world point to local box space
          const toLocal = (n: {x: number, y: number, z: number}) => {
            const vx = n.x - pX;
            const vy = n.y - pY;
            const vz = n.z - pZ;
            const tx = 2 * (uy * vz - uz * vy);
            const ty = 2 * (uz * vx - ux * vz);
            const tz = 2 * (ux * vy - uy * vx);
            return {
              x: vx + w * tx + (uy * tz - uz * ty),
              y: vy + w * ty + (uz * tx - ux * tz),
              z: vz + w * tz + (ux * ty - uy * tx)
            };
          };

          const lA = toLocal(nA);
          const lB = toLocal(nB);

          let isCut = false;
          let cutPointLocal = [0, 0, 0];
          let cutPointWorld = [0, 0, 0];

          // Check if spring crosses the X plane of the chainsaw bounding box
          if ((lA.x <= sX && lB.x >= -sX) || (lB.x <= sX && lA.x >= -sX)) {
             // Find the exact intersection fraction with the X=0 plane
             const distA = Math.abs(lA.x);
             const distB = Math.abs(lB.x);
             const totalDistX = distA + distB;
             const f = totalDistX > 0.000001 ? distA / totalDistX : 0.5;
             
             const yInt = lA.y + (lB.y - lA.y) * f;
             const zInt = lA.z + (lB.z - lA.z) * f;

             if (Math.abs(yInt) <= sY && Math.abs(zInt) <= sZ) {
                isCut = true;
                cutPointLocal = [0, yInt, zInt];
                cutPointWorld = [
                  nA.x + (nB.x - nA.x) * f,
                  nA.y + (nB.y - nA.y) * f,
                  nA.z + (nB.z - nA.z) * f
                ];
             }
          }

          if (isCut) {
            console.log(`[Physics Worker] Spring ${spring.idxA}-${spring.idxB} broken. World: [${cutPointWorld.map(n => n.toFixed(3)).join(', ')}], local: [${cutPointLocal.map(n => n.toFixed(3)).join(', ')}]`);
            spring.broken = true;
            springsBroken++;
          }
        }
      }

      if (springsBroken > 0) {
        console.log(`[Physics Worker] Snapped ${springsBroken} Kerf Springs!`);
      }
    }
  } else if (data.type === 'SET_GUIDEBAR') {
    const guidebarData = data as any; // SetGuidebarMessage
    if (solver) {
      solver.setGuidebar(guidebarData.active, guidebarData.boxPosition, guidebarData.boxQuaternion, guidebarData.boxScale);
    }
  } else if (data.type === 'SET_HAND_FORCE') {
    const handData = data as any; // Cast to bypass strict type error if needed, but it's SetHandForceMessage
    handForceActive = handData.active;
    if (handForceActive && handData.point && handData.direction && handData.magnitude !== undefined) {
      handForcePoint = handData.point;
      handForceDir = handData.direction;
      handForceMag = handData.magnitude;
    }
  } else if (data.type === 'SET_WEDGE') {
    const wedgeData = data as any;
    if (solver) {
      if (wedgeData.action === 'start') {
        solver.startWedge(wedgeData.id, wedgeData.kerfIndex ?? 0, wedgeData.radialPosition ?? 'top', wedgeData.sliceIndex);
      } else if (wedgeData.action === 'drive') {
        solver.driveWedge(wedgeData.id, wedgeData.depthIncrement);
      } else if (wedgeData.action === 'stop') {
        solver.stopDrivingWedge(wedgeData.id);
      } else if (wedgeData.action === 'remove') {
        solver.removeWedge(wedgeData.id);
      } else if (wedgeData.action === 'clear') {
        solver.clearWedges();
      }
    }
  } else if (data.type === 'SET_TELEMETRY') {
    showPerfWarnings = data.showPerfWarnings;
  } else if (data.type === 'SET_SHOW_TENSION') {
    showTension = data.showTension;
  } else if (data.type === 'SET_GRAVITY') {
    const gravityData = data as SetGravityMessage;
    setGravity(-gravityData.gravity);
  } else if (data.type === 'INITIATE_CUT') {
    const cutData = data as CutMessage;
    console.log(`[Physics Worker] INITIATE_CUT received: Point(${cutData.planePoint.map(n => n.toFixed(2)).join(',')}), Normal(${cutData.planeNormal.map(n => n.toFixed(2)).join(',')})`);

    if (logModel) {
      logModel.initiateKerf(cutData.planePoint, cutData.planeNormal);

      // Reallocate buffers (Float32Arrays are immutable in size)
      positionsBuffer = new Float32Array(logModel.nodes.length * 3);
      strainsBuffer = new Float32Array(logModel.nodes.length);

      // Notify main thread to rebuild Visuals
      self.postMessage({
        type: 'RESIZE_BUFFERS',
        nodeCount: logModel.nodes.length
      });

      const springsArray = new Int32Array(logModel.springs.length * 2);
      for (let i = 0; i < logModel.springs.length; i++) {
        springsArray[i * 2] = logModel.springs[i].idxA;
        springsArray[i * 2 + 1] = logModel.springs[i].idxB;
      }

      self.postMessage({
        type: 'TOPOLOGY',
        segments: logModel.segments,
        kerfs: logModel.activeKerfs,
        springs: springsArray
      });
    }
  }
};

function tick() {
  if (!solver) return;

  const t0 = performance.now();

  if (handForceActive) {
    solver.applyExternalForce(handForcePoint, handForceDir, handForceMag);
  }

  solver.tick(showTension);

  const t1 = performance.now();
  const executionTime = t1 - t0;

  // Telemetry check requested in 03_physics_engine.md
  if (showPerfWarnings) {
    console.log(`[Physics Worker] Frame compute time: ${executionTime.toFixed(2)}ms (Target: <16.6ms)`);
  }

  // Populate array buffer
  logModel.getPositionsBuffer(positionsBuffer);
  if (showTension) {
    logModel.getStrainsBuffer(strainsBuffer);
  }

  // Collect broken kerf spring states
  let brokenKerfSprings: boolean[][] | undefined = undefined;
  if (logModel.activeKerfs.length > 0) {
    brokenKerfSprings = [];
    for (const kerf of logModel.activeKerfs) {
      const kerfStates = [];
      for (const sIdx of kerf.springIndices) {
        kerfStates.push(logModel.springs[sIdx].broken);
      }
      brokenKerfSprings.push(kerfStates);
    }
  }

  // Send back to main thread (copying the array buffer is very fast for small arrays)
  const msg: SyncMessage = {
    type: 'SYNC',
    positions: positionsBuffer,
    strains: showTension ? strainsBuffer : undefined,
    brokenKerfSprings,
    bindingPressure: solver.getBindingPressure(),
    wedges: solver.getWedgesState(),
    timestamp: performance.now()
  };

  self.postMessage(msg);
}
